import{_ as s,c as t,o as r,j as e,a as n}from"./chunks/framework.Dnh4IO1K.js";const _=JSON.parse('{"title":"周易尚氏学自序","description":"周易尚氏学 - 周易尚氏学自序","frontmatter":{"title":"周易尚氏学自序","description":"周易尚氏学 - 周易尚氏学自序"},"headers":[],"relativePath":"zh/classics/shangshi/003.md","filePath":"zh/classics/shangshi/003.md"}'),i={name:"zh/classics/shangshi/003.md"};function c(o,a,l,d,h,p){return r(),t("div",null,[...a[0]||(a[0]=[e("h1",{id:"周易尚氏学自序",tabindex:"-1"},[n("周易尚氏学自序 "),e("a",{class:"header-anchor",href:"#周易尚氏学自序","aria-label":"Permalink to “周易尚氏学自序”"},"​")],-1),e("p",null,"易理至明也。而说者多误。说何以误。厥有二因。一因易理之失传。太史公曰。易以道阴阳。阴阳之理。同性相敌。异性相感。艮传云上下敌应。不相与也。谓阳应阳阴应阴为敌也。中孚六三云得敌。同人九三曰敌刚。谓阴比阴阳比阳为敌也。阴遇阴。阳遇阳。既为敌而不相与。则不能为朋友为类明矣。咸传曰二气感应以相与。恒曰刚柔皆应。夫阴阳相与相应。则必相求而为朋友为类明矣。复曰朋来无咎。谓阳来也。阴以阳为朋也。损曰一人行则得其友。谓阳行至上而据二阴也。阳以阴为友也。颐六二曰行失类也。谓阴不遇阳也。至明白也。乃说者于坤上六。谓阴阳相战争。相伤而出血矣。于文言谓阴阳相忌相疑矣。以阳遇阳为朋。阴遇阴为友为类矣。同性相敌。异性相感之理一失。于是初四二五三上阳应阳阴应阴者谓之失应。人尚知之。至于阳比阳阴比阴。如夬垢之三四。如颐之六二。说者则茫然。于是全部易。如征凶。往吝。往不胜。壮于趾。其行次且。及慎所之等辞。全不知其故矣。又如阳遇重阴。阴遇重阳而当位者。所谓往吉。征吉。利涉。利往。上合志也。此其义宋蔡渊曾创言之。而未大行。于是全部易爻象若是者。自汉迄清。说者亦莫明其故。而用爻变矣。又如阳爻，下乘重阴者亦多吉。与前临重阴同也。蹇九三日内喜之也。说甚明也。乃亦失传。于是颐上九之利涉。蒙上九渐九三之利御寇。皆不知所谓矣。有此一因。于是易解之误者。十而四五。其次则象学失传。说卦乃自古相传之卦象。祗说其纲领。以为万象之引伸。并示其推广之义。如干为马。坤震坎亦可为马。干为龙。震亦可为龙。巽为木。艮坎亦可为木。非谓甲卦象此物。乙卦即不许再象也。视其义何如耳。至文王时。又历数千年。其所演易象。必益广益精。故周易所用象。往往与说卦不同。说卦以坎为月。经则多以兑为月。月生西。坎兑皆位西也。说卦以离为龟。经则以艮为龟。离为龟。取其外坚。艮亦外坚也。此推而益广也。且有与说卦相反者。说卦以兑为少女。以艮为少男。而经则以兑为老妇，以艮为祖为丈夫。说卦以震为长男。巽为长女。经则以震为小子。巽为少女 (女妻即少女) 。盖以甲乙言。先生者长。后生者少。而以一人言。则初生者少。行至上而老也。此演而益精也。自东汉迄清。于此等义例。都未能明。见经所用象。为说卦所无。则用卦变爻变或爻辰以求之。谬法流传。二千年如一日。加此一因。于是易解之误者。十而七八矣。以二千年相承之易说。今忽谓其误。以一人之是。谓千百人皆非。毋乃骇众。然而易象固在也。易理固存也。本易理以诂易辞。如磁铁之吸引。由易辞以准易象。如规凿之相投。固不诬也。以为之者少。旁无师友之助。以违之者众。更无声气之同。然而我见固如斯也。我说无一创也。以我之说。仍以周易所言之理。推而正说者之误。俾卦爻辞复其本有之易理也。其先儒旧说。与易理合者。如许慎荀爽九家之诂龙战。如子夏传荀爽之诂得敌，靡不因也，其与易理盩者。虽千百人皆如此言。而必反之。如虞翻以阳遇阳为朋。阴遇阴为类等是也。至于卦象之误者。非我能创造新象。仍周易原有之象。说者失之。今证以左传国语。周公时训与卦气图。证以焦氏易林郭璞洞林。回环互证而得其象也。及其既得而求其本。仍在周易。如坤之为水为鱼。震之为輹等象是也。然而我之说不敢必谓其是也。更不敢自匿其非也。故名曰周易尚氏学。以质世之治易者。经者天下之公物。非一人所得私。理者天地之自然。非偏执所能改。倘学易之君子。见是编而扬搉其是非。纠正其疏漏。则日夜所祈祷者也。",-1)])])}const f=s(i,[["render",c]]);export{_ as __pageData,f as default};
